changeSet.sql:
DROP TABLE IF EXISTS tenant_user_profiles CASCADE;
CREATE TABLE tenant_user_profiles ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), global_user_id UUID NOT NULL, first_name VARCHAR(128) NOT NULL, last_name VARCHAR(128) NOT NULL, role VARCHAR(64) NOT NULL, permission_matrix JSONB NOT NULL DEFAULT '[]'::jsonb, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT uq_tenant_user_profiles_global_user_id UNIQUE (global_user_id) );
CREATE INDEX idx_tenant_profiles_perm_gin ON tenant_user_profiles USING gin (permission_matrix);

DROP TABLE IF EXISTS tenant_user_addresses CASCADE;
CREATE TABLE tenant_user_addresses ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), profile_id UUID NOT NULL REFERENCES tenant_user_profiles(id) ON DELETE CASCADE, address_type VARCHAR(32) NOT NULL DEFAULT 'SHIPPING', recipient_name VARCHAR(128) NOT NULL, phone VARCHAR(32) NOT NULL, address_line1 VARCHAR(255) NOT NULL, address_line2 VARCHAR(255), city VARCHAR(128) NOT NULL, state VARCHAR(128) NOT NULL, postal_code VARCHAR(32) NOT NULL, country_code VARCHAR(8) NOT NULL DEFAULT 'IN', is_default BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0 );
CREATE INDEX idx_tenant_addresses_profile_id ON tenant_user_addresses (profile_id);
